        // Validate every destination before sending the first number.
        for(const [key,value] of draft.commands){const f=FIELDS.find(f=>f[0]===key),s=this.state(key);if(!f||!Number.isInteger(value)||value<f[2]||value>f[3]||value<Number(s.attributes.min)||value>Number(s.attributes.max)||!Number.isFinite(Number(s.attributes.min))||!Number.isFinite(Number(s.attributes.max)))throw Error('recipe-range');}
